import React, { useState } from 'react';
import Login from './Login';
import SignUp from './SignUp';

const LoginPage = ({ onLogin }) => {
    const [isSigningUp, setIsSigningUp] = useState(false);


    const handleSignUpSuccess = (token, username) => {
        console.log("Sign-up successful, logging in:", username);
        onLogin(token, username); 
    };

    return (
        <div style={styles.container}>
            <h1 style={styles.heading}>{isSigningUp ? 'Sign Up' : 'Log In'}</h1>
            <div style={styles.authBox}>
                {isSigningUp ? (
                    <SignUp onSignUpSuccess={handleSignUpSuccess} />
                ) : (
                    <Login onLogin={onLogin} />
                )}
                {/* Move button inside auth box */}
                <button onClick={() => setIsSigningUp((prev) => !prev)} style={styles.toggleButton}>
                    {isSigningUp
                        ? 'Already have an account? Log in'
                        : "Don't have an account? Sign Up"}
                </button>
            </div>
        </div>
    );
};

const styles = {
    container: {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        backgroundColor: '#f9f9f9',
    },
    heading: {
        fontSize: '24px',
        marginBottom: '20px',
        fontWeight: 'bold',
    },
    authBox: {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        width: '320px',
        padding: '20px',
        backgroundColor: 'white',
        boxShadow: '0px 4px 6px rgba(0, 0, 0, 0.1)',
        borderRadius: '8px',
    },
    toggleButton: {
        marginTop: '15px',
        backgroundColor: 'transparent',
        border: 'none',
        color: '#007bff',
        cursor: 'pointer',
        fontSize: '14px',
        textDecoration: 'underline',
    }
};

export default LoginPage;
